package com.acme.heritage.guide;

import java.time.Duration;
import java.util.List;

/**
 * Estimates the time a visitor should allow for a site visit.
 */
public class VisitDurationEstimator {

    private static final Duration BASE_PER_CATEGORY = Duration.ofMinutes(20);
    private static final Duration PER_POINT_OF_INTEREST = Duration.ofMinutes(8);

    private final PointOfInterestRepository points;

    public VisitDurationEstimator(PointOfInterestRepository points) {
        this.points = points;
    }

    public Duration estimate(HeritageSite site) {
        List<PointOfInterest> pois = points.findBySite(site.getId());
        Duration base = BASE_PER_CATEGORY.multipliedBy(site.getCategory().getWeight());
        Duration poiTime = PER_POINT_OF_INTEREST.multipliedBy(pois.size());
        return base.plus(poiTime);
    }
}

