package com.acme.heritage.guide;

import java.util.Optional;

/**
 * Resolves a scanned marker to a point of interest and prepares playback.
 */
public class MarkerPlaybackService {

    private final MarkerRepository markers;
    private final AudioAssetRepository audio;
    private final TranscriptRepository transcripts;

    public MarkerPlaybackService(MarkerRepository markers, AudioAssetRepository audio,
                                 TranscriptRepository transcripts) {
        this.markers = markers;
        this.audio = audio;
        this.transcripts = transcripts;
    }

    public PlaybackResponse play(String markerCode, String preferredLang, boolean accessibilityMode) {
        PointOfInterest poi = markers.resolve(markerCode)
            .orElseThrow(() -> new UnknownMarkerException(markerCode));
        String audioUrl = audio.urlFor(poi.getId(), preferredLang);
        Optional<String> transcript = accessibilityMode
            ? transcripts.find(poi.getId(), preferredLang)
            : Optional.empty();
        return new PlaybackResponse(poi, audioUrl, transcript);
    }
}

