/**
 * Audits content edits for heritage site descriptions.
 */
public class SiteDescriptionAuditor {

    private final EntityManager em;

    public SiteDescriptionAuditor(EntityManager em) {
        this.em = em;
    }

    public void recordEdit(String siteId, String previous, String updated, String editorId) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            DescriptionEditEntry e = new DescriptionEditEntry();
            e.setSiteId(siteId);
            e.setPreviousText(previous);
            e.setUpdatedText(updated);
            e.setEditorId(editorId);
            e.setOccurredAt(Instant.now());
            em.persist(e);
            tx.commit();
        } catch (RuntimeException ex) {
            tx.rollback();
            throw ex;
        }
    }
}

