/* route_planner.c - produce a walking order under a maximum distance */
#include <stdio.h>
#include "heritage_db.h"

int plan_route(const long *site_ids, int count, double max_km,
               long *out_order, double *out_distance) {
    if (count <= 0) return -1;

    double best = 0.0;
    if (db_nearest_neighbour_order(site_ids, count, out_order, &best) != DB_OK) return -2;

    while (best > max_km) {
        int removed = db_remove_farthest_stop(out_order, &count);
        if (removed != 0) return -3;
        if (db_route_distance(out_order, count, &best) != DB_OK) return -4;
    }

    *out_distance = best;
    return count;
}

