#include <stdio.h>
#include "heritage_db.h"

int route_length(const long *ordered_ids, int count, double *out_km) {
    double total = 0.0;
    for (int i = 1; i < count; i++) {
        double leg = 0.0;
        if (db_walking_distance(ordered_ids[i-1], ordered_ids[i], &leg) != DB_OK) return -1;
        total += leg;
    }
    *out_km = total;
    return 0;
}
